/* 内嵌游戏字体（思源黑体 Noto Sans SC，OFL；subset-font.py 子集化产出，勿手改）。
 * 自执行：FontFace 注册 family=MoanSans（400/700），完成后全局重绘切换字形。 */
window.MOAN_FONTS = { regular: "", bold: "" };
(function () {
  if (typeof FontFace === 'undefined' || !document.fonts) return;
  function buf(b64) {
    var bin = atob(b64), a = new Uint8Array(bin.length);
    for (var i = 0; i < bin.length; i++) a[i] = bin.charCodeAt(i);
    return a.buffer;
  }
  function reg(b64, weight) {
    return new FontFace('MoanSans', buf(b64), { weight: weight }).load()
      .then(function (f) { document.fonts.add(f); });
  }
  Promise.all([reg(window.MOAN_FONTS.regular, '400'), reg(window.MOAN_FONTS.bold, '700')])
    .then(function () { if (window.__moan && window.__moan.invalidate) window.__moan.invalidate(); })
    .catch(function (e) { if (typeof console !== 'undefined') console.warn('[moan] 字体注册失败', e); });
})();
